Function.prototype.myBind = function (thisArg, ...presetArgs) {
  const targetFn = this; // the function bind was called on
  if (typeof targetFn !== 'function') throw new TypeError('not callable');

  function bound(...callArgs) {
    const allArgs = [...presetArgs, ...callArgs];
    // If called with `new`, ignore thisArg and use the new instance.
    const isNew = this instanceof bound;
    return targetFn.apply(isNew ? this : thisArg, allArgs);
  }

  // Preserve the prototype chain for `new boundFn()` / instanceof.
  bound.prototype = Object.create(targetFn.prototype || Object.prototype);
  return bound;
};

