const ok = (v, ms) => new Promise((r) => setTimeout(() => r(v), ms));
const fail = (e, ms) => new Promise((_, rej) => setTimeout(() => rej(e), ms));

async function demo() {
  // all: rejects on first failure
  try { await Promise.all([ok('a', 10), fail('boom', 5)]); }
  catch (e) { console.log('all rejected:', e); } // 'boom'

  // race: first to settle (here a rejection) wins
  try { await Promise.race([ok('slow', 30), fail('fast-err', 5)]); }
  catch (e) { console.log('race rejected:', e); } // 'fast-err'

  // allSettled: never throws, reports every outcome
  const settled = await Promise.allSettled([ok('x', 5), fail('y', 5)]);
  console.log(settled.map((s) => s.status)); // ['fulfilled', 'rejected']

  // any: first fulfillment wins, ignores earlier rejections
  const winner = await Promise.any([fail('e1', 5), ok('won', 10)]);
  console.log('any resolved:', winner); // 'won'
}
demo();

function debounce(fn, delay = 300, { leading = false } = {}) {
  let timer = null;
  function debounced(...args) {
    const callNow = leading && timer === null;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!leading) fn.apply(this, args); // trailing edge
    }, delay);
    if (callNow) fn.apply(this, args);    // leading edge
  }
  debounced.cancel = () => { clearTimeout(timer); timer = null; };
  return debounced;
}

