// Manual iterator implementation
const rangeManual = {
  from: 1,
  to: 4,
  [Symbol.iterator]() {
    let current = this.from;
    const last = this.to;
    return {
      next() {
        return current <= last
          ? { value: current++, done: false }
          : { value: undefined, done: true };
      },
    };
  },
};
console.log([...rangeManual]); // [1, 2, 3, 4]

// Generator version: same behavior, far less code
function* range(from, to) {
  for (let i = from; i <= to; i++) yield i;
}
console.log([...range(1, 4)]);        // [1, 2, 3, 4]
for (const n of range(5, 7)) console.log(n); // 5, 6, 7

