// map and filter expressed with reduce
const mapWith = (arr, fn) => arr.reduce((acc, x, i) => (acc.push(fn(x, i)), acc), []);
const filterWith = (arr, pred) => arr.reduce((acc, x) => (pred(x) && acc.push(x), acc), []);

console.log(mapWith([1, 2, 3], (x) => x * 2)); // [2, 4, 6]
console.log(filterWith([1, 2, 3, 4], (x) => x % 2 === 0)); // [2, 4]

// One reduce -> grouped summary (total spend per user)
const orders = [
  { user: 'a', amount: 10 },
  { user: 'b', amount: 5 },
  { user: 'a', amount: 7 },
];
